.season-chip span{width: 7px; height: 7px; border-radius: 999px; background: var(--gold); box-shadow: rgba(215, 170, 97, 0.55) 0px 0px 18px;}
.header-cta{justify-self: end; display: flex; gap: 12px; align-items: center;}
.header-cta button{height: 44px; padding: 0px 18px; border-radius: 999px; border: 1px solid rgba(95, 73, 42, 0.08); background: rgba(255, 255, 255, 0.2); color: white; text-transform: uppercase; letter-spacing: 0.22em; font-size: 10px; transition: 0.35s;}
.header-cta button:hover{background: rgba(255, 255, 255, 0.66); transform: translateY(-2px);}
.header-bottom{border-top: 1px solid rgba(95, 73, 42, 0.08); padding: 10px 28px 12px; display: flex; gap: 28px; align-items: center; justify-content: center; text-transform: uppercase; letter-spacing: 0.22em; font-size: 10px; color: white; overflow-x: auto; scrollbar-width: none;}
.header-bottom::-webkit-scrollbar{display: none;}
.header-bottom a{text-decoration: none; color: inherit; white-space: nowrap; transition: 0.25s;}
.header-bottom a:hover{color: rgb(172, 123, 63);}
@media (max-width: 1100px){.header-top{grid-template-columns: 1fr auto;}}
@media (max-width: 1100px){.season-chip{display: none;}}
@media (max-width: 768px){.header-top{padding: 14px 16px 10px;}}
@media (max-width: 768px){.header-bottom{justify-content: flex-start; padding: 10px 16px 12px;}}
.min-w-0{min-width: 0px;}
.text-2xl{font-size: 1.5rem; line-height: 2rem;}
.text-\[11px\]{font-size: 11px;}
.text-sm{font-size: 0.875rem; line-height: 1.25rem;}
.uppercase{text-transform: uppercase;}
.leading-tight{line-height: 1.25;}
.tracking-\[0\.34em\]{letter-spacing: 0.34em;}
.text-\[\#9b7a3d\]{--tw-text-opacity: 1; color: rgb(155 122 61 / var(--tw-text-opacity, 1));}
.text-white\/80{color: rgba(255, 255, 255, 0.8);}
.text-white\/90{color: rgba(255, 255, 255, 0.9);}
